  esac
}

_copilot() {
  local cur prev cword words
  if declare -F _get_comp_words_by_ref >/dev/null 2>&1; then
    _get_comp_words_by_ref -n =: cur prev cword words
  else
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD - 1]}"
    cword=$COMP_CWORD
    words=("${COMP_WORDS[@]}")
  fi

  local ___copilot_required='--add-dir --add-github-mcp-tool --add-github-mcp-toolset --additional-mcp-config --agent --attachment --context --disable-mcp-server --effort --env --extension-sdk-path --header --host --interactive --kind --log-dir --log-level --max-ai-credits --max-autopilot-continues --mode --model --name --output-format --plugin-dir --prompt --reasoning-effort --scope --session-id --stream --timeout --tools --transport -C -i -n -p'
  local ___copilot_optional='--bash-env --connect --mouse --resume --share -r'
  local ___copilot_variadic='--allow-tool --allow-url --available-tools --deny-tool --deny-url --excluded-tools --secret-env-vars'

  # Walk words[1..cword-1] to detect the current subcommand path. At the
  # `--` end-of-options marker, count any trailing positionals then stop.
  # Value-taking flags consume tokens differently:
  #   required (`--foo <v>`):   always consume next token as value
  #   optional (`--foo [v]`):   consume next only if it isn't a flag or a
  #                            known subcommand at the current path
  #   variadic (`--foo [v...]`): keep consuming under the same rule
  local __path="" __i=1 __mode=none __argidx=0
  while [ $__i -lt $cword ]; do
    local __w="${words[$__i]}"
    if [ "$__w" = "--" ]; then
      # End-of-options: every following token is a positional operand.
      # Count the completed ones (up to the word being completed) so an
      # already-filled positional slot isn't re-offered.
      __i=$((__i + 1))
      while [ $__i -lt $cword ]; do
        __argidx=$((__argidx + 1))
        __i=$((__i + 1))
      done
      break
    fi

    if [ "$__mode" = "required" ]; then
      __mode=none
      __i=$((__i + 1))
      continue
    fi

    if [ "$__mode" = "optional" ] || [ "$__mode" = "variadic" ]; then
      local __candidate
      if [ -n "$__path" ]; then
        __candidate="$__path $__w"
      else
        __candidate="$__w"
      fi
      if [ "${__w#-}" != "$__w" ] || ___copilot_is_known_path "$__candidate"; then
        # Not a value — stop consuming and reprocess this token.
        __mode=none
      else
        # Consume as value. Optional clears the mode after one token.
        if [ "$__mode" = "optional" ]; then __mode=none; fi
        __i=$((__i + 1))
        continue
      fi
    fi

    if [ "${__w#--*=}" != "$__w" ]; then
      : # --flag=value form, no extra skip
    elif [ "${__w#-}" != "$__w" ]; then
      case " $___copilot_required " in *" $__w "*) __mode=required ;; esac
      case " $___copilot_optional " in *" $__w "*) __mode=optional ;; esac
      case " $___copilot_variadic " in *" $__w "*) __mode=variadic ;; esac
    else
      local __candidate2
      if [ -n "$__path" ]; then
        __candidate2="$__path $__w"
      else
        __candidate2="$__w"
      fi
      if ___copilot_is_known_path "$__candidate2"; then
        __path="$__candidate2"
        __argidx=0
      else
        # A plain word that isn't a subcommand is a positional value;
        # advance the positional index for the resolved path.
        __argidx=$((__argidx + 1))
      fi
    fi
    __i=$((__i + 1))
  done

  # If the previous token is a value-taking flag with declared choices,
  # suggest those choices.
  case "$prev" in
  --model)
    COMPREPLY=($(compgen -W 'auto claude-sonnet-5 claude-fable-5 claude-opus-5 claude-opus-4.8 claude-opus-4.8-fast claude-opus-4.7 claude-sonnet-4.6 claude-opus-4.6 claude-sonnet-4.5 claude-opus-4.5 claude-haiku-4.5 gpt-5.6-sol gpt-5.6-terra gpt-5.6-luna gpt-5.5 gpt-5.4 gpt-5.4-mini gpt-5.3-codex gpt-5-mini mai-code-1-flash-picker gemini-3.7-flash gemini-3.6-flash gemini-3.5-flash gemini-3.1-pro-preview grok-4.5 kimi-k3 kimi-k2.7-code' -- "$cur"))
    return 0
    ;;
  --effort | --reasoning-effort)
    COMPREPLY=($(compgen -W 'none minimal low medium high xhigh max' -- "$cur"))
    return 0
    ;;
  --context)
    COMPREPLY=($(compgen -W 'default long_context' -- "$cur"))
    return 0
    ;;
  --log-level)
    COMPREPLY=($(compgen -W 'none error warning info debug all default' -- "$cur"))
    return 0
    ;;
  --stream)
    COMPREPLY=($(compgen -W 'on off' -- "$cur"))
    return 0
    ;;
  --output-format)
    COMPREPLY=($(compgen -W 'text json' -- "$cur"))
    return 0
    ;;
  --mode)
    COMPREPLY=($(compgen -W 'interactive plan autopilot' -- "$cur"))
    return 0
    ;;
  --transport)
    COMPREPLY=($(compgen -W 'stdio http sse' -- "$cur"))
    return 0
    ;;
  esac

