  # not a subcommand/flag slot. Emit no candidates so `complete -o default`
  # falls back to filename completion (correct for path flags like --add-dir,
  # harmless otherwise) -- matching the fish generator. `__mode` is non-none
  # here only for such flags (choice flags already returned above). A required
  # flag's value is mandatory, so route to filenames even when the current word
  # starts with a dash (`--prompt --<Tab>`); for optional/variadic flags the
  # `cur` guard preserves flag completion (e.g. `--resume --<flag>`).
  if [ "$__mode" = "required" ] || { [ "$__mode" != "none" ] && [ "${cur#-}" = "$cur" ]; }; then
    COMPREPLY=()
    return 0
  fi

